import json,math

def integrate(a):
    root=a['ROOT'];book=a['book'];add=a['add'];tab=a['tab'];img=a['img'];out=root/'tmp/pdfs/wall_moments'
    d=json.loads((out/'summary.json').read_text(encoding='utf8'));ch='第5章 / 施工例B：擁壁とSRM'
    oldids={k:id(book[n-1]) for k,n in a['source_map'].items()};new=[]
    def page(title,parts):add(title,parts,ch);new.append(book.pop())
    page('擁壁の曲げ：隅角の最大応力と断面力を分ける',[
        '線形弾性の鋭い入隅は応力特異点になり得ます。隅角の局所最大応力は、メッシュを細かくするほど増えて収束しないことがあります。「細分化すれば特異点が解消する」という扱いはしません。今回の2メッシュだけで特異性の次数や発散自体を実証したわけでもありません。',
        tab([['確認対象','何を比較するか'],['角の最大応力','ピークの低下を合否基準にしない。角の形状・接続・材料境界を確認。実際の丸みをモデル化する場合はその寸法根拠を残す。'],['縦壁・底盤の曲げ','部材断面の応力を積分しN・V・Mを求める。断面位置を物理座標で固定し、粗密差と釣合いを確認する。'],['接合部の扱い','角そのものは梁断面の解釈も難しい。角からの距離をmおよび部材厚との比で示し、複数断面で感度を調べる。'],['部材設計','連続体の弾性応力からの断面力整理と、RCのひび割れ・配筋・耐力照査を区別する。']],[1.2,4]),
        '断面積分は特異点のピークより安定する場合がありますが、自動的に精度保証されるわけではありません。粗密で断面力が近くても、応力復元・境界の力・自重との釣合いが悪ければ設計値に採用しません。',
        '参考[S9] Ansys「Assessing Stress Singularity」。局所ピークと、応力積分による膜力・モーメントを区別する考え方を参照。圧力容器等の応力分類を本擁壁の設計規準へそのまま転用するものではありません。'])
    page('曲げを取り出すためのメッシュと断面位置',[
        img(out/'mesh_plan_schematic.png',205),
        '上は今後の比較計画の模式図です。厚さ方向2→4→8分割など、応力勾配を表せる整った要素列で比較します。この分割数は精度の保証や全案件共通の推奨値ではありません。Q8でも厚さ1要素の結果だけで十分とは判断しません。',
        tab([['作成・修正の注意','本例での確認'],['材料と接続','壁・土を領域分割し、共有境界の節点を一致させる。重複要素・隙間を作らず、断面積分は壁材料だけを選ぶ。'],['要素の形','極端な細長さ・歪み・急な寸法変化を避ける。Jacobianの正だけで曲げ精度まで認定しない。'],['断面線に沿う分割','縦壁は水平、底盤は鉛直の評価線を決め、厚さ方向の分割線と整合させる。現行メッシャーでは生成後の節点・接続を必ず確認する。'],['比較位置を固定','「角から2要素先」では細分化で場所が動く。角(18.6,0.4)に対し縦壁y=1.8、底盤x=18.0等、同じ座標で比較。']],[1.2,4]),
        '既存の粗40・細68壁要素は自動生成された不整形メッシュです。この模式図の厚さ2/4/8分割を実行した結果ではなく、掲載値を厚さ方向の収束試験済みとは扱いません。'])
    page('出力設定：工程と積分点の応力を残す',[
        '施工完了時の曲げを見るには、工程3（背面盛土BIRTH完了）・Fs=1の保存結果を使います。工程4のSRM最終収束状態は、地盤強度を低減した別の状態です。両者を混ぜて通常時の曲げとしません。',
        tab([['設定 / データ','断面力整理での使い方'],['出力・表示 C9=ALL','工程ごとの結果を保存。C10=SKIPを基本とし、有効な壁要素だけを対象にする。ログはC11=STAGEを入口にする。'],['結果要素','A=工程、B=要素ID。G1のσx/σy/τxyはE/F/G、G2はV/W/X、G3はAM/AN/AO、G4はBD/BE/BF。17列/GPの並びを確認。'],['節点・要素データ','座標、Q8の8節点接続、材料番号を保持する。本例は材料2のみ。土の応力を壁断面へ足さない。'],['材料と工程の記録','壁E=25,000,000kPa、ν=0.2、γ=24kN/m³、奥行1m、STRUCT、SRM低減対象外。初期地盤→壁→盛土の順。'],['図と数値の違い','応力図の平滑化・色範囲や変形倍率は断面積分の入力値ではない。画面の色や最大主応力だけからMを逆算しない。']],[1.25,3.95]),
        '元ブックは2DSoilFEM_ui_20261020.xlsmの検証コピー。wall_davis08/12の保存済み工程3を再整理しました。今回はExcel再計算やブック・VBA・DLLの変更をしていません。元の倍精度・材料則・収束条件を保持します。'])
    page('断面力の求め方：符号・単位・4GPからの復元',[
        '保存応力Cは圧縮正のテンソルです。ここでは引張正T=−C（せん断成分も反転）へ統一し、断面の正側法線nに対する表面力t=Tnを作ります。Nは引張正、Mzは反時計回り正です。反対側の切断面を使えば符号も反転します。',
        tab([['断面','単位奥行の積分式'],['縦壁：n=+Y','x=18.6～19.0、xc=18.8。N=−∫Cyy dx、V=−∫Cxy dx、Mz=−∫(x−xc)Cyy dx。'],['底盤：n=+X','y=0～0.4、yc=0.2。N=−∫Cxx dy、V=−∫Cxy dy、Mz=+∫(y−yc)Cxx dy。'],['共通の定義','Mz=∫[(r−rc)×(Tn)]z ds。N,VはkN/m、MzはkN·m/m。奥行1m当たり。壁厚0.4mと奥行を混同しない。']],[1.3,3.9]),
        '断面と各Q8要素境界の交点を求め、要素内の4GP応力を自然座標の1,r,s,rsで近似復元し、切断線に沿って積分します。GP応力を単に平均して断面積を掛ける方法では、厚さ方向の曲げ勾配を失います。',
        'これは保存4GPからの後処理近似で、厳密な応力場・要素節点内力の復元ではありません。断面の±10^(-7)mから得た値の平均と両側値・差をCSVへ保存。要素境界の応力不連続があれば片側値も確認します。',
        '一定膜応力＋線形曲げ応力＋一定せん断の解析解を、X/Y断面・厚さ1/3分割の4条件で照合しました。最大絶対差1.78×10^(-15)。実断面の線積分12点/24点差は2×10^(-4)未満。ただしこの検査は実メッシュの精度収束や釣合いを保証しません。'])
    page('実計算から整理する：同じ工程・同じ断面',[
        img(out/'actual_meshes.png',290),
        '粗：1,857節点・580 Q8（壁40）、細：3,383節点・1,074 Q8（壁68）。色は基盤・壁・背面盛土で、変形前の入力形状です。赤線は比較断面。図の縦横比は等しく、壁厚は縦壁・底盤とも0.4mです。',
        '縦壁はy=0.6～3.2の9断面、底盤はx=15.2～18.4の10断面を同じ座標で比較しました。底盤断面はx<18.6とし、壁脚の接合領域を単純な高さ0.4mの底盤断面として切り抜きません。',
        '地盤と壁は節点を共有した接続です。接触・剥離・滑り、鉄筋やひび割れを表す専用部材要素はありません。施工履歴と接続条件を含む結果であり、自由な片持ち梁に単純な三角形土圧を掛けた解と同一視しません。'])
    def r(case,part,s):return next(x for x in d['records'] if x['case']==case and x['part']==part and x['station_m']==s)
    vals=[]
    for part,s,label in [('stem',1.8,'縦壁 y=1.8'),('base',18.,'底盤 x=18.0'),('base',18.4,'底盤 x=18.4')]:
        u,v=r('wall_davis08',part,s),r('wall_davis12',part,s)
        vals.append([label,f"{u['Mz_kNm_per_m']:.3f}",f"{v['Mz_kNm_per_m']:.3f}",f"{v['Mz_kNm_per_m']-u['Mz_kNm_per_m']:+.3f}"])
    page('曲げモーメント：粗密比較と断面位置の影響',[
        img(out/'moment_comparison.png',245),
        tab([['断面','粗 Mz','細 Mz','細−粗'],*vals],[1.8,1,1,1]),
        '単位kN·m/m。縦壁y=1.8の細メッシュN=−32.452kN/m、V=+3.428kN/m、Mz=+5.914kN·m/m。底盤x=18.0はN=+9.188、V=+13.685、Mz=−10.566です。曲線は指定断面間を結んだもので、未評価位置の極値保証ではありません。',
        '底盤x=18.0では|M|の差は粗基準で約1.4%ですが、壁脚に近いx=18.4では約13.3%。縦壁y=0.8はMが零に近く、百分率より絶対差で読みます。近い2値だけを選んで「曲げが収束した」とは結論しません。'])
    rr=[]
    for x in d['closed_subdomain_checks']:
        rr.append(['粗' if x['case'].endswith('08') else '細',('縦壁上部 y=' if x['part']=='stem' else '底盤左部 x=')+str(x['station_m']),f"{math.hypot(*x['force_closure_kN_per_m']):.3f}",f"{x['moment_closure_kNm_per_m']:+.3f}"])
    page('釣合い診断と、この例の採用できる範囲',[
        tab([['メッシュ','切り出した部分','力の不釣合い','Mの不釣合い'],*rr],[.7,2,1.2,1.3]),
        '力はkN/m、MはkN·m/m。縦壁は断面より上、底盤は断面より左の長方形領域を切り出し、周囲4辺の復元表面力＋自重（γ=24）を積分しました。Mは赤線断面の図心まわり。絶対値ではなく符号付きMz残差を表に示しています。',
        '細メッシュでも底盤のM不釣合いは−18.955kN·m/mで、断面|M|=10.566より大きく、無視できません。辺の復元力同士が相殺するため、全表面力で正規化した数%だけを示して良好とは判定しません。縦壁のM不釣合いも+0.645で、検証が終わった値ではありません。',
        'この診断は復元応力場の局所釣合いです。元ソルバーの節点内力残差とは異なり、独立に既知の境界反力と照合した証明でもありません。記録された計算の収束と、後処理した部材曲げの精度は分けて判断します。',
        '本例は出力からN・V・Mを整理する方法と、既存メッシュの限界を示す実例です。設計に使うには厚さ方向を整えた段階的な細分化、同一座標での断面比較、応力復元法・節点内力/境界反力との照合を追加します。角の最大応力を採用せず、RC断面照査は別途行います。',
        '再現資料：construction-evidence/20261021/wall-moment-guideのsections.csv、summary.json、rebuild_sections.py。38断面、両側値、積分点数比較、出典SHAを収録。参考[S9] https://innovationspace.ansys.com/courses/courses/tips-and-tricks-for-structural-simulation-in-ansys-mechanical/lessons/assessing-stress-singularity/'])
    pos=next(i for i,row in enumerate(book) if row['title']=='擁壁施工後SRM：結果とせん断帯')
    book[pos:pos]=new
    for k,ident in oldids.items():a['source_map'][k]=next(i for i,row in enumerate(book,1) if id(row)==ident)
